#include "tao_joint_selector.hpp"
#include <cuda_runtime.h>
#include <cstdio>
void ck(cudaError_t e){if(e!=cudaSuccess)throw std::runtime_error(cudaGetErrorString(e));}
// Fixed tiny oracle batch:two candidates,three dimensions, five alternatives.
__global__ void kernel(const double*r,const double*v,const double*z,const double*u,double*out){if(threadIdx.x||blockIdx.x)return;double p[5],b[5][3],y[3]={},m=z[0],sum=0;for(int k=1;k<5;++k)m=fmax(m,z[k]);for(int k=0;k<5;++k){p[k]=exp((z[k]-m)/.7);sum+=p[k];}for(int k=0;k<5;++k){p[k]/=sum;for(int d=0;d<3;++d){b[k][d]=k==0?r[d]:(k%2==1?.7*r[d]+.3*v[((k-1)/2)*3+d]:r[d]+.4*v[((k-1)/2)*3+d]);y[d]+=p[k]*b[k][d];}}for(int d=0;d<3;++d)out[d]=y[d];for(int k=0;k<5;++k){double influence=0;for(int d=0;d<3;++d)influence+=u[d]*(b[k][d]-y[d]);out[3+k]=p[k]*influence/.7;}}
int main(){try{using namespace tao::joint;Input x{{.2,-.5,1},{{1,2,-1},{-.4,.6,.2}},{.2,-.8,1.1,.4,-.1},.7,.3,.4};Vector u{.3,-.8,.5},flat{1,2,-1,-.4,.6,.2};double *r,*v,*z,*du,*o;ck(cudaMalloc(&r,24));ck(cudaMalloc(&v,48));ck(cudaMalloc(&z,40));ck(cudaMalloc(&du,24));ck(cudaMalloc(&o,64));ck(cudaMemcpy(r,x.original.data(),24,cudaMemcpyHostToDevice));ck(cudaMemcpy(v,flat.data(),48,cudaMemcpyHostToDevice));ck(cudaMemcpy(z,x.logits.data(),40,cudaMemcpyHostToDevice));ck(cudaMemcpy(du,u.data(),24,cudaMemcpyHostToDevice));kernel<<<1,1>>>(r,v,z,du,o);ck(cudaGetLastError());double got[8];ck(cudaMemcpy(got,o,64,cudaMemcpyDeviceToHost));auto y=forward(x);auto g=backward(x,u);double err=0;for(int i=0;i<8;++i){if(!std::isfinite(got[i]))throw std::runtime_error("nonfinite");double ref=i<3?y.soft[i]:g.logits[i-3];err=std::max(err,std::abs(ref-got[i]));}if(err>1e-12)throw std::runtime_error("parity");ck(cudaFree(r));ck(cudaFree(v));ck(cudaFree(z));ck(cudaFree(du));ck(cudaFree(o));printf("PASS CUDA joint soft output and logits gradient max_abs=%.12g tiny oracle only\n",err);return 0;}catch(const std::exception&e){fprintf(stderr,"FAIL %s\n",e.what());return 1;}}
